preConditionHook:
// THE 3/10 OSCILLATOR -- Grimes's fast line, in the settled form (merge
// decision 2): the difference of two SIMPLE averages of the close,
//     osc = average of close over fastLen bars, less the average
//           of close over slowLen bars
// with fastLen 3 and slowLen 10 as the book's defaults. Never the MACD word.
// EL's Average RECOMPUTES from scratch every bar (VERIFIED: matched a fresh
// loop on 2,808/2,808 bars; it is NOT a rolling accumulator like the WFSafe_
// wrappers), and Summation adds the newest bar first and works backwards,
// with a single divide at the end -- which is how the loops below run.
// Both averages run over a PRICE expression, which has real bar history, so
// they are recomputed from the bars rather than mirrored; only osc ITSELF is
// a variable, and that is what the ring buffer below mirrors. Copied from
// OscillatorAboveZero and OscillatorNewExtreme, the family's reference pair.
// The whole quantity is a difference of prices, so it passes the shift test.
// Scratch is declared in localVariables, never at hook scope: the generator
// only prefixes declared locals, so a hook-scope declaration is a
// redefinition when the rule is placed twice in one strategy.
oscFast = 0.0;
for (int i = 0; i < (int)fastLen; ++i) {
    oscFast += close[i];
}
oscFast = oscFast / (int)fastLen;
oscSlow = 0.0;
for (int i = 0; i < (int)slowLen; ++i) {
    oscSlow += close[i];
}
oscSlow = oscSlow / (int)slowLen;
osc = oscFast - oscSlow;
// NO MOMENTUM DIVERGENCE IN THE LAST sinceDivergenceBars BARS -- Grimes's
// "long trades should not be entered on the next pullback" after a divergence.
// Stated POSITIVELY: true when no divergence fired anywhere in the window.
//
// The divergence test is MomentumDivergenceAtSwingExtreme's, term for term
// (merge decision 3, window maxima, no pivot scan), evaluated at each of the
// last sinceDivergenceBars bars with its own one-bar-shifted window. A single
// negated placement of that rule cannot express this -- it tests the current
// bar only -- which is why the bounded OR is its own file, the same relation
// NoClimaxBarInWindow has to its primitive.
//
// osc is an EL VARIABLE, so osc[k] reads the variable's OWN history, which
// holds its initial 0 for every bar before the strategy's first evaluated one.
// Mirrored as a zero-seeded ring buffer, re-seeded if the depth ever changes
// (AwesomeOscillatorSlope / OscillatorNewExtreme / AtrRising). Depth
// sinceDivergenceBars + divLookback so lags 0 .. sinceDivergenceBars +
// divLookback - 1 all live in the buffer.
oscDepth = (int)sinceDivergenceBars + (int)divLookback;
if (oscDepth < 2) {
    oscDepth = 2;
}
if (oscHistory.size() != (std::size_t)oscDepth) {
    oscHistory.assign((std::size_t)oscDepth, 0.0);
    oscCursor = 0;
}
oscHistory[oscCursor] = osc;
oscCursor = (oscCursor + 1) % oscHistory.size();
// WARM-UP: the zero-filled osc pre-history would manufacture divergences, so
// nothing is scanned until every bar the scan can reach is a real reading.
// While divReady is false both flags stay false and the rule reads TRUE -- an
// all-clear filter must not block on a warm-up reading.
divReady = ctx.CurrentBar() > (int)sinceDivergenceBars + (int)divLookback;
divUp = false;
divDn = false;
if (divReady) {
    for (ii = 0; ii <= (int)sinceDivergenceBars - 1; ++ii) {
        pHigh = high[ii + 1];
        pLow = low[ii + 1];
        oscPeak = oscHistory[(oscCursor + oscHistory.size() - 1 - (std::size_t)(ii + 1)) % oscHistory.size()];
        oscTrough = oscPeak;
        for (jj = 2; jj <= (int)divLookback; ++jj) {
            if (el_gt(high[ii + jj], pHigh)) {
                pHigh = high[ii + jj];
            }
            if (el_lt(low[ii + jj], pLow)) {
                pLow = low[ii + jj];
            }
            double v = oscHistory[(oscCursor + oscHistory.size() - 1 - (std::size_t)(ii + jj)) % oscHistory.size()];
            if (el_gt(v, oscPeak)) {
                oscPeak = v;
            }
            if (el_lt(v, oscTrough)) {
                oscTrough = v;
            }
        }
        double oi = oscHistory[(oscCursor + oscHistory.size() - 1 - (std::size_t)ii) % oscHistory.size()];
        if (el_ge(high[ii], pHigh) && el_lt(oi, oscPeak)) {
            divUp = true;
        }
        if (el_le(low[ii], pLow) && el_gt(oi, oscTrough)) {
            divDn = true;
        }
    }
}
